INSERT INTO rag_interpretations (category, planet, sign, keywords, interpretation_text, element, quality, language) VALUES
('planet_in_sign', 'Sun', 'Aries', ARRAY['лидерство','инициатива','импульсивность','энергичность'], 'Солнце в Овне дарит яркий, энергичный характер, стремление быть первым и лидерскую жилку. Человек прямолинеен, инициативен и не боится препятствий.', 'Fire', 'Cardinal', 'ru'),
('planet_in_sign', 'Sun', 'Taurus', ARRAY['стабильность','практичность','терпение','материализм'], 'Солнце в Тельце даёт спокойный, практичный и надёжный характер. Человек ценит комфорт, красоту и материальную безопасность.', 'Earth', 'Fixed', 'ru'),
('planet_in_sign', 'Sun', 'Gemini', ARRAY['коммуникабельность','любознательность','гибкость','интеллект'], 'Солнце в Близнецах наделит лёгкостью общения, любознательностью и многогранностью интересов. Человек быстро схватывает информацию и легко адаптируется.', 'Air', 'Mutable', 'ru'),
('planet_in_sign', 'Sun', 'Cancer', ARRAY['чувствительность','заботливость','интуиция','эмоциональность'], 'Солнце в Раке делает человека глубоко эмоциональным, заботливым и привязанным к дому и семье. Сильная интуиция и потребность в безопасности.', 'Water', 'Cardinal', 'ru'),
('planet_in_sign', 'Sun', 'Leo', ARRAY['творчество','харизма','гордость','щедрость'], 'Солнце во Льве — классический знак творческой самовыраженности, харизмы и внутреннего достоинства. Человек стремится к признанию и обладает щедрым сердцем.', 'Fire', 'Fixed', 'ru'),
('planet_in_sign', 'Sun', 'Virgo', ARRAY['аналитичность','практичность','критичность','сервис'], 'Солнце в Деве даёт аналитический склад ума, стремление к порядку и полезности. Человек внимателен к деталям и склонен к самосовершенствованию.', 'Earth', 'Mutable', 'ru'),
('planet_in_sign', 'Sun', 'Libra', ARRAY['гармония','дипломатичность','эстетика','справедливость'], 'Солнце в Весах наделяет стремлением к гармонии, справедливости и эстетике. Человек дипломатичен, ценит партнёрство и умеет видеть обе стороны конфликта.', 'Air', 'Cardinal', 'ru'),
('planet_in_sign', 'Sun', 'Scorpio', ARRAY['глубина','интенсивность','трансформация','магнетизм'], 'Солнце в Скорпионе даёт мощную эмоциональную глубину, интенсивность и стремление к трансформации. Человек обладает магнетизмом и умением видеть скрытое.', 'Water', 'Fixed', 'ru'),
('planet_in_sign', 'Sun', 'Sagittarius', ARRAY['оптимизм','философия','свобода','экспансия'], 'Солнце в Стрельце дарит оптимизм, философский взгляд на жизнь и тягу к приключениям. Человек честен, прямолинеен и стремится к расширению горизонтов.', 'Fire', 'Mutable', 'ru'),
('planet_in_sign', 'Sun', 'Capricorn', ARRAY['амбиции','дисциплина','ответственность','статус'], 'Солнце в Козероге наделяет амбициозностью, дисциплиной и чувством долга. Человек целеустремлён, терпелив и стремится к статусу через достижения.', 'Earth', 'Cardinal', 'ru'),
('planet_in_sign', 'Sun', 'Aquarius', ARRAY['оригинальность','независимость','гуманизм','инновации'], 'Солнце в Водолее даёт независимый, оригинальный взгляд на мир и стремление к прогрессу. Человек гуманен, дружелюбен и ценит интеллектуальную свободу.', 'Air', 'Fixed', 'ru'),
('planet_in_sign', 'Sun', 'Pisces', ARRAY['сострадание','интуиция','творчество','мечтательность'], 'Солнце в Рыбах наделяет глубоким состраданием, богатым внутренним миром и творческими способностями. Человек чувствителен, интуитивен и склонен к самопожертвованию.', 'Water', 'Mutable', 'ru');
INSERT INTO rag_interpretations (category, planet, sign, keywords, interpretation_text, element, quality, language) VALUES
('planet_in_sign', 'Moon', 'Aries', ARRAY['эмоциональная импульсивность','независимость','страсть'], 'Луна в Овне даёт эмоциональную импульсивность и потребность в немедленном удовлетворении желаний. Человек реагирует быстро, страстно и независимо.', 'Fire', 'Cardinal', 'ru'),
('planet_in_sign', 'Moon', 'Taurus', ARRAY['эмоциональная стабильность','чувственность','привязанность'], 'Луна в Тельце — сильная позиция, дающая эмоциональную стабильность, чувственность и потребность в комфорте. Человек верен, терпелив и ценит постоянство.', 'Earth', 'Fixed', 'ru'),
('planet_in_sign', 'Moon', 'Gemini', ARRAY['эмоциональная подвижность','любопытство','общительность'], 'Луна в Близнецах делает эмоциональную сферу подвижной и любопытной. Человек нуждается в интеллектуальной стимуляции, разговорах и разнообразии.', 'Air', 'Mutable', 'ru'),
('planet_in_sign', 'Moon', 'Cancer', ARRAY['глубокая эмоциональность','забота','память'], 'Луна в Раке — домашняя позиция. Человек обладает глубокой эмоциональной чувствительностью, сильной привязанностью к дому, семье и прошлому.', 'Water', 'Cardinal', 'ru'),
('planet_in_sign', 'Moon', 'Leo', ARRAY['эмоциональная щедрость','драматичность','творчество'], 'Луна во Льве наделяет эмоциональной щедростью, драматичностью и потребностью в любви и внимании. Человек тёплый, верный и творческий.', 'Fire', 'Fixed', 'ru'),
('planet_in_sign', 'Moon', 'Virgo', ARRAY['эмоциональная сдержанность','анализ','полезность'], 'Луна в Деве даёт сдержанность в проявлении эмоций и стремление помогать другим. Человек эмоционально реагирует через заботу, анализ и практические действия.', 'Earth', 'Mutable', 'ru'),
('planet_in_sign', 'Moon', 'Libra', ARRAY['эмоциональная гармония','партнёрство','эстетика'], 'Луна в Весах делает эмоциональную сферу зависимой от гармонии в отношениях. Человек дипломатичен, нуждается в партнёре и ценит красоту.', 'Air', 'Cardinal', 'ru'),
('planet_in_sign', 'Moon', 'Scorpio', ARRAY['эмоциональная интенсивность','тайны','трансформация'], 'Луна в Скорпионе даёт интенсивные, глубокие эмоции и стремление к эмоциональной близости. Человек обладает сильной интуицией, но может быть ревнив и подозрителен.', 'Water', 'Fixed', 'ru'),
('planet_in_sign', 'Moon', 'Sagittarius', ARRAY['эмоциональный оптимизм','свобода','философия'], 'Луна в Стрельце дарит эмоциональный оптимизм, потребность в свободе и философский взгляд на чувства. Человек открыт, честен и любит приключения.', 'Fire', 'Mutable', 'ru'),
('planet_in_sign', 'Moon', 'Capricorn', ARRAY['эмоциональная сдержанность','ответственность','контроль'], 'Луна в Козероге наделяет эмоциональной сдержанностью и стремлением к контролю над чувствами. Человек серьёзен, надёжен, но может быть слишком строг к себе.', 'Earth', 'Cardinal', 'ru'),
('planet_in_sign', 'Moon', 'Aquarius', ARRAY['эмоциональная независимость','дружба','прогресс'], 'Луна в Водолее даёт независимость в эмоциональной сфере и ценность дружбы. Человек объективен, гуманен, но может казаться отстранённым.', 'Air', 'Fixed', 'ru'),
('planet_in_sign', 'Moon', 'Pisces', ARRAY['эмоциональная чувствительность','сострадание','мечты'], 'Луна в Рыбах наделяет глубокой эмоциональной чувствительностью, состраданием и богатым воображением. Человек впечатлителен и склонен к эмпатии.', 'Water', 'Mutable', 'ru');
INSERT INTO rag_interpretations (category, planet, sign, keywords, interpretation_text, element, quality, language) VALUES
('planet_in_sign', 'Ascendant', 'Aries', ARRAY['внешняя активность','инициатива','боец'], 'Асцендент в Овне придаёт внешность энергичность и решительность. Человек кажется инициативным, прямым и готовым к действию.', 'Fire', 'Cardinal', 'ru'),
('planet_in_sign', 'Ascendant', 'Taurus', ARRAY['внешняя спокойствие','чувственность','стабильность'], 'Асцендент в Тельце даёт спокойную, надёжную внешность. Человек кажется практичным, чувственным и терпеливым.', 'Earth', 'Fixed', 'ru'),
('planet_in_sign', 'Ascendant', 'Gemini', ARRAY['внешняя коммуникабельность','подвижность','юность'], 'Асцендент в Близнецах делает человека кажущимся молодым, подвижным и общительным. Лёгкость в общении и любознательность заметны с первой встречи.', 'Air', 'Mutable', 'ru'),
('planet_in_sign', 'Ascendant', 'Cancer', ARRAY['внешняя мягкость','заботливость','чувствительность'], 'Асцендент в Раке придаёт мягкую, заботливую внешность. Человек кажется чувствительным, семейным и защитным.', 'Water', 'Cardinal', 'ru'),
('planet_in_sign', 'Ascendant', 'Leo', ARRAY['внешняя харизма','театральность','уверенность'], 'Асцендент во Льве даёт яркую, харизматичную внешность. Человек кажется уверенным, творческим и достойным внимания.', 'Fire', 'Fixed', 'ru'),
('planet_in_sign', 'Ascendant', 'Virgo', ARRAY['внешняя скромность','аккуратность','аналитичность'], 'Асцендент в Деве делает человека кажущимся аккуратным, скромным и внимательным к деталям. Практичность и полезность видны сразу.', 'Earth', 'Mutable', 'ru'),
('planet_in_sign', 'Ascendant', 'Libra', ARRAY['внешняя привлекательность','дипломатичность','грация'], 'Асцендент в Весах придаёт грациозную, привлекательную внешность. Человек кажется дипломатичным, вежливым и стремящимся к гармонии.', 'Air', 'Cardinal', 'ru'),
('planet_in_sign', 'Ascendant', 'Scorpio', ARRAY['внешняя интенсивность','магнетизм','тайна'], 'Асцендент в Скорпионе даёт интенсивную, магнетическую внешность. Человек кажется загадочным, глубоким и проницательным.', 'Water', 'Fixed', 'ru'),
('planet_in_sign', 'Ascendant', 'Sagittarius', ARRAY['внешний оптимизм','открытость','движение'], 'Асцендент в Стрельце делает человека кажущимся открытым, оптимистичным и энергичным. Любовь к свободе и путешествиям заметна сразу.', 'Fire', 'Mutable', 'ru'),
('planet_in_sign', 'Ascendant', 'Capricorn', ARRAY['внешняя серьёзность','ответственность','статус'], 'Асцендент в Козероге придаёт серьёзную, деловую внешность. Человек кажется ответственным, амбициозным и статусным.', 'Earth', 'Cardinal', 'ru'),
('planet_in_sign', 'Ascendant', 'Aquarius', ARRAY['внешняя оригинальность','независимость','дружелюбие'], 'Асцендент в Водолее делает человека кажущимся оригинальным, независимым и дружелюбным. Эксцентричность и прогрессивность заметны с первой встречи.', 'Air', 'Fixed', 'ru'),
('planet_in_sign', 'Ascendant', 'Pisces', ARRAY['внешняя мечтательность','мягкость','эмпатия'], 'Асцендент в Рыбах придаёт мягкую, мечтательную внешность. Человек кажется чувствительным, добрым и немного загадочным.', 'Water', 'Mutable', 'ru');
INSERT INTO rag_interpretations (category, planet, house, keywords, interpretation_text, language) VALUES
('planet_in_house', 'Sun', 1, ARRAY['личность','самовыражение','идентичность'], 'Солнце в 1 доме делает личность яркой и заметной. Человек идентифицирует себя через самовыражение, лидерство и инициативу.', 'ru'),
('planet_in_house', 'Sun', 2, ARRAY['финансы','ценности','самооценка'], 'Солнце во 2 доме указывает, что самооценка и материальное благополучие важны для личности. Человек стремится зарабатывать и ценить себя.', 'ru'),
('planet_in_house', 'Sun', 3, ARRAY['коммуникация','обучение','родственники'], 'Солнце в 3 доме делает коммуникацию, обучение и отношения с родственниками центральными для самовыражения.', 'ru'),
('planet_in_house', 'Sun', 4, ARRAY['дом','семья','корни'], 'Солнце в 4 доме указывает на важность дома, семьи и внутреннего уюта для личности. Человек стремится создать прочную основу.', 'ru'),
('planet_in_house', 'Sun', 5, ARRAY['творчество','любовь','дети','удовольствие'], 'Солнце в 5 доме делает творчество, романтику, детей и удовольствия ключевыми сферами самовыражения.', 'ru'),
('planet_in_house', 'Sun', 6, ARRAY['работа','здоровье','сервис','рутина'], 'Солнце в 6 доме указывает на важность работы, здоровья и помощи другим. Человек находит себя через служение и дисциплину.', 'ru'),
('planet_in_house', 'Sun', 7, ARRAY['партнёрство','брак','отношения'], 'Солнце в 7 доме делает партнёрства и отношения центром самовыражения. Человек раскрывается через взаимодействие с другими.', 'ru'),
('planet_in_house', 'Sun', 8, ARRAY['трансформация','ресурсы партнёра','оккультизм'], 'Солнце в 8 доме указывает на интерес к глубинным трансформациям, совместным ресурсам и тайнам жизни.', 'ru'),
('planet_in_house', 'Sun', 9, ARRAY['философия','путешествия','высшее образование'], 'Солнце в 9 доме делает философию, путешествия и расширение сознания важными для самовыражения.', 'ru'),
('planet_in_house', 'Sun', 10, ARRAY['карьера','статус','публичность','амбиции'], 'Солнце в 10 доме — сильная позиция для карьеры и публичности. Человек стремится к статусу и признанию.', 'ru'),
('planet_in_house', 'Sun', 11, ARRAY['друзья','группы','социальные идеалы'], 'Солнце в 11 доме указывает на важность дружбы, групп и социальных идеалов для самовыражения.', 'ru'),
('planet_in_house', 'Sun', 12, ARRAY['уединение','духовность','подсознание'], 'Солнце в 12 доме делает духовность, уединение и работу с подсознанием важными для личности.', 'ru');
INSERT INTO rag_interpretations (category, planet, house, keywords, interpretation_text, language) VALUES
('planet_in_house', 'Moon', 1, ARRAY['эмоции','личность','реакция'], 'Луна в 1 доме делает эмоции и настроение заметными для окружающих. Человек реагирует интуитивно и чувствителен.', 'ru'),
('planet_in_house', 'Moon', 4, ARRAY['дом','семья','эмоциональная безопасность'], 'Луна в 4 доме указывает на сильную привязанность к дому, семье и эмоциональной безопасности.', 'ru'),
('planet_in_house', 'Moon', 7, ARRAY['эмоциональное партнёрство','брак'], 'Луна в 7 доме делает эмоциональное партнёрство и брак важнейшими для внутреннего комфорта.', 'ru'),
('planet_in_house', 'Moon', 10, ARRAY['карьера','публичность','эмоции на работе'], 'Луна в 10 доме указывает на эмоциональную вовлеченность в карьеру и публичную жизнь.', 'ru');
INSERT INTO rag_interpretations (category, aspect_type, p1, p2, keywords, interpretation_text, language) VALUES
('aspect', 'conjunction', 'Sun', 'Moon', ARRAY['единство','гармония','целостность'], 'Солнце в соединении с Луной даёт целостность личности, гармонию между волей и эмоциями. Человек уверен в себе и эмоционально сбалансирован.', 'ru'),
('aspect', 'conjunction', 'Sun', 'Mercury', ARRAY['интеллект','коммуникация','ясность'], 'Солнце в соединении с Меркурием наделяет ясным умом, сильной коммуникативной способностью и интеллектуальной активностью.', 'ru'),
('aspect', 'conjunction', 'Sun', 'Venus', ARRAY['красота','гармония','обаяние'], 'Солнце в соединении с Венерой даёт обаяние, любовь к красоте и гармонии. Человек дружелюбен и ценит эстетику.', 'ru'),
('aspect', 'conjunction', 'Sun', 'Mars', ARRAY['энергия','решительность','борьба'], 'Солнце в соединении с Марсом наделяет огромной энергией, решительностью и стремлением к действию.', 'ru'),
('aspect', 'conjunction', 'Moon', 'Mercury', ARRAY['эмоциональный интеллект','память'], 'Луна в соединении с Меркурием даёт эмоциональный интеллект, сильную память и способность выражать чувства словами.', 'ru'),
('aspect', 'trine', 'Sun', 'Moon', ARRAY['лёгкость','гармония','уверенность'], 'Солнце в тригоне к Луне — очень благоприятный аспект, дающий внутреннюю гармонию, уверенность и эмоциональную стабильность.', 'ru'),
('aspect', 'trine', 'Sun', 'Jupiter', ARRAY['удача','оптимизм','расширение'], 'Солнце в тригоне к Юпитеру дарит оптимизм, удачу и способность к расширению возможностей.', 'ru'),
('aspect', 'opposition', 'Sun', 'Saturn', ARRAY['ограничения','ответственность','напряжение'], 'Солнце в оппозиции к Сатурну указывает на внутреннее напряжение между самовыражением и ограничениями. Человек учится дисциплине через трудности.', 'ru'),
('aspect', 'square', 'Sun', 'Pluto', ARRAY['трансформация','власть','кризис'], 'Солнце в квадрате к Плутону указывает на глубокие трансформации через кризисы власти и контроля.', 'ru');
INSERT INTO rag_interpretations (category, house, keywords, interpretation_text, language) VALUES
('house_meaning', 1, ARRAY['личность','внешность','я'], '1 дом — дом личности, внешности и жизненной позиции. Описывает, как человек воспринимается миром и как реагирует на жизнь.', 'ru'),
('house_meaning', 2, ARRAY['финансы','ценности','ресурсы'], '2 дом — дом материальных ресурсов, ценностей и самооценки. Показывает отношение к деньгам и способности к заработку.', 'ru'),
('house_meaning', 3, ARRAY['коммуникация','обучение','родственники'], '3 дом — дом коммуникации, обучения, ближнего окружения и родственников. Описывает интеллектуальные способности и повседневные контакты.', 'ru'),
('house_meaning', 4, ARRAY['дом','семья','корни','конец жизни'], '4 дом — дом семьи, корней, домашнего очага и внутренней безопасности. Также связан с концом жизненного пути.', 'ru'),
('house_meaning', 5, ARRAY['творчество','любовь','дети','удовольствие'], '5 дом — дом творчества, романтики, детей и удовольствий. Показывает, как человек выражает радость и любовь.', 'ru'),
('house_meaning', 6, ARRAY['работа','здоровье','сервис','рутина'], '6 дом — дом работы, здоровья, служения и повседневной рутины. Описывает отношение к труду и самочувствию.', 'ru'),
('house_meaning', 7, ARRAY['партнёрство','брак','контракты'], '7 дом — дом партнёрства, брака, открытых врагов и контрактов. Показывает тип партнёров и стиль отношений.', 'ru'),
('house_meaning', 8, ARRAY['трансформация','совместные ресурсы','оккультизм'], '8 дом — дом трансформации, совместных ресурсов, наследства и тайн. Связан с глубинными изменениями.', 'ru'),
('house_meaning', 9, ARRAY['философия','путешествия','высшее образование'], '9 дом — дом философии, высшего образования, путешествий и расширения сознания. Показывает мировоззрение.', 'ru'),
('house_meaning', 10, ARRAY['карьера','статус','публичность','амбиции'], '10 дом — дом карьеры, статуса, публичности и социального признания. Описывает профессиональные амбиции.', 'ru'),
('house_meaning', 11, ARRAY['друзья','группы','социальные идеалы'], '11 дом — дом дружбы, групп, социальных идеалов и будущих надежд. Показывает отношение к коллективу.', 'ru'),
('house_meaning', 12, ARRAY['уединение','духовность','подсознание','тайные враги'], '12 дом — дом уединения, духовности, подсознания и тайных врагов. Связан с скрытыми аспектами жизни.', 'ru');
INSERT INTO rag_interpretations (category, sign, keywords, interpretation_text, element, quality, language) VALUES
('sign_meaning', 'Aries', ARRAY['лидерство','инициатива','импульсивность'], 'Овен — первый знак зодиака, стихия Огонь, крест Кардинальный. Символизирует начало, лидерство, импульсивность и смелость.', 'Fire', 'Cardinal', 'ru'),
('sign_meaning', 'Taurus', ARRAY['стабильность','практичность','чувственность'], 'Телец — знак земной стихии, крест Фиксированный. Символизирует стабильность, практичность, чувственность и терпение.', 'Earth', 'Fixed', 'ru'),
('sign_meaning', 'Gemini', ARRAY['коммуникабельность','любознательность','гибкость'], 'Близнецы — воздушный знак, крест Мутабельный. Символизирует коммуникацию, любознательность, многогранность и адаптивность.', 'Air', 'Mutable', 'ru'),
('sign_meaning', 'Cancer', ARRAY['чувствительность','забота','интуиция'], 'Рак — водный знак, крест Кардинальный. Символизирует эмоции, заботу, интуицию и привязанность к дому.', 'Water', 'Cardinal', 'ru'),
('sign_meaning', 'Leo', ARRAY['творчество','харизма','гордость'], 'Лев — огненный знак, крест Фиксированный. Символизирует творчество, харизму, самовыражение и щедрость.', 'Fire', 'Fixed', 'ru'),
('sign_meaning', 'Virgo', ARRAY['аналитичность','практичность','критичность'], 'Дева — земной знак, крест Мутабельный. Символизирует анализ, порядок, практичность и стремление к совершенству.', 'Earth', 'Mutable', 'ru'),
('sign_meaning', 'Libra', ARRAY['гармония','дипломатичность','эстетика'], 'Весы — воздушный знак, крест Кардинальный. Символизирует гармонию, справедливость, дипломатию и эстетику.', 'Air', 'Cardinal', 'ru'),
('sign_meaning', 'Scorpio', ARRAY['глубина','интенсивность','трансформация'], 'Скорпион — водный знак, крест Фиксированный. Символизирует глубину, интенсивность, трансформацию и магнетизм.', 'Water', 'Fixed', 'ru'),
('sign_meaning', 'Sagittarius', ARRAY['оптимизм','философия','свобода'], 'Стрелец — огненный знак, крест Мутабельный. Символизирует оптимизм, философию, свободу и расширение горизонтов.', 'Fire', 'Mutable', 'ru'),
('sign_meaning', 'Capricorn', ARRAY['амбиции','дисциплина','ответственность'], 'Козерог — земной знак, крест Кардинальный. Символизирует амбиции, дисциплину, ответственность и стремление к вершинам.', 'Earth', 'Cardinal', 'ru'),
('sign_meaning', 'Aquarius', ARRAY['оригинальность','независимость','гуманизм'], 'Водолей — воздушный знак, крест Фиксированный. Символизирует оригинальность, независимость, прогресс и гуманизм.', 'Air', 'Fixed', 'ru'),
('sign_meaning', 'Pisces', ARRAY['сострадание','интуиция','творчество'], 'Рыбы — водный знак, крест Мутабельный. Символизирует сострадание, интуицию, творчество и духовность.', 'Water', 'Mutable', 'ru');
